<?php
namespace Database\Seeders;use Illuminate\Database\Seeder;use App\Models\{Currency,DebtType,Organization};use Spatie\Permission\Models\{Role,Permission};
class DatabaseSeeder extends Seeder{public function run():void{foreach(['manage organizations','manage subscriptions','manage settings','view global statistics','manage users','manage debts','manage payments','view reports','create debts','create payments','view limited reports'] as $p)Permission::firstOrCreate(['name'=>$p]);foreach(['Super Admin','Organization Admin','Accountant','Data Entry'] as $r)Role::firstOrCreate(['name'=>$r]);foreach([['USD','US Dollar','$'],['EUR','Euro','€'],['SYP','Syrian Pound','ل.س'],['TRY','Turkish Lira','₺']] as $c)Currency::firstOrCreate(['code'=>$c[0]],['name'=>$c[1],'symbol'=>$c[2]]);$org=Organization::firstOrCreate(['code'=>'DEMO'],['name'=>'Demo Organization']);foreach(['Credit Sale','Service Invoice','Advance','Rent','Other'] as $t)DebtType::firstOrCreate(['organization_id'=>$org->id,'name'=>$t]);}}
